-- World fixes: tower skirmishes get every player class and an elite pool (2026-11-26)
-- Four, after the class pool: "expand the pool to all player classes, expand their kit and give them an additional
-- skill or two. and yes, give the last wave a pool just like the others ... but keeping the last wave elite"
-- (wave 4 had always been the warrior elite). Health and damage of the regulars stay where they were.
-- Each run now picks four different classes out of all thirteen: waves 1-3 are regulars of the first three, wave 4
-- is the elite of the fourth (tools/bfa/tower-skirmish-all-classes.patch, after tower-skirmish-class-pool.patch).
-- New regulars per faction and zone: Crusader (paladin), Confessor (priest), Runeblade (death knight), Windwalker
-- (monk), Grovewarden (druid), Felblade (demon hunter). New elites: Frostweaver, Flameweaver, Huntmaster (+ pet),
-- Stormcaller, Doomcaller (+ imp), Nightblade, Justicar, High Confessor, Deathlord, Grandmaster, Archdruid,
-- Felreaver; the warrior elite stays the Warbringer / Vanguard. Elites take the warrior elite's step up (health x2.27,
-- damage x1.33 of their class's regular), are one level above the player, and Enrage at 30% health.
-- Bigger kits for the seven first regulars: warrior + Rend, Demoralizing Shout; frost mage + Frost Armor, Cone of
-- Cold; fire mage + Flamestrike; hunter + Arcane Shot, Wing Clip, Raptor Strike; shaman + Flame Shock, Chain
-- Lightning; warlock + Curse of Agony, Drain Life; rogue + Gouge, Evasion at 50%.
-- Our own design: NPC spells of TDB 8.3.7 era mobs, looks of TDB 8.3.7 faction NPCs (Blood Knights, Ironforge
-- Paladins, Ebon Blade, Huojin / Tushui monks, Illidari). flags_extra 2112 = honor kill + no XP.
-- Entries: Thrallmar 9100137-9100154, Honor Hold 9100155-9100172, Stonebreaker 9100173-9100190, Allerian
-- 9100191-9100208; in each block + 0-5 the regulars paladin .. demon hunter, + 6-17 the elites frost mage .. demon
-- hunter. Replaces the scripts of the first regulars from 2026_11_25_30, 2026_11_26_30 and 2026_11_26_31 (run this
-- one after them). Safe to run twice.

DELETE FROM `creature_template` WHERE `entry` BETWEEN 9100137 AND 9100208;

-- Level scaling like the zone's soldiers (Hellfire 58-83, Terokkar 62-83); elites one level above the player
DELETE FROM `creature_template_scaling` WHERE `Entry` BETWEEN 9100137 AND 9100208;

-- Looks: Blood Knights / Ironforge Paladins, Expeditionary / Dun Garok Priests, Knights of the Ebon Blade, Huojin /
-- Tushui Monks, Bloodhoof Healers / Darnassian Druids, Illidari; elites wear their class's regular looks
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 9100137 AND 9100208;

DELETE FROM `creature_equip_template` WHERE `CreatureID` BETWEEN 9100137 AND 9100208;

-- Fighting: the kits above, for the new soldiers and the first regulars (the warrior elites keep theirs)
DELETE FROM `smart_scripts` WHERE (`entryorguid` IN (9100101,9100102,9100113,9100114,9100115,9100116,9100117,9100104,9100105,9100118,9100119,9100120,9100121,9100122,9100107,9100108,9100123,9100124,9100125,9100126,9100127,9100110,9100111,9100128,9100129,9100130,9100131,9100132) OR `entryorguid` BETWEEN 9100137 AND 9100208) AND `source_type`=0;

-- Summary: expect 72 soldiers, 72 scaling rows, 198 models, 60 weapons, 516 scripts
SELECT (SELECT COUNT(*) FROM `creature_template` WHERE `entry` BETWEEN 9100137 AND 9100208) AS `soldiers`,
       (SELECT COUNT(*) FROM `creature_template_scaling` WHERE `Entry` BETWEEN 9100137 AND 9100208) AS `scaling`,
       (SELECT COUNT(*) FROM `creature_template_model` WHERE `CreatureID` BETWEEN 9100137 AND 9100208) AS `models`,
       (SELECT COUNT(*) FROM `creature_equip_template` WHERE `CreatureID` BETWEEN 9100137 AND 9100208) AS `weapons`,
       (SELECT COUNT(*) FROM `smart_scripts` WHERE (`entryorguid` IN (9100101,9100102,9100113,9100114,9100115,9100116,9100117,9100104,9100105,9100118,9100119,9100120,9100121,9100122,9100107,9100108,9100123,9100124,9100125,9100126,9100127,9100110,9100111,9100128,9100129,9100130,9100131,9100132) OR `entryorguid` BETWEEN 9100137 AND 9100208) AND `source_type`=0) AS `scripts`;
